parameters.jsCode:
const staticData = $getWorkflowStaticData('global');
if (!staticData.notifiedUsers) staticData.notifiedUsers = {};

const messages = $('WhatsApp Trigger').item.json.messages || [];
const phone = messages[0]?.from;
const now = Date.now();
const COOLDOWN_MS = 24 * 60 * 60 * 1000; // 24 hours

if (phone && staticData.notifiedUsers[phone] && (now - staticData.notifiedUsers[phone] < COOLDOWN_MS)) {
  return []; // notified within last 24h, skip
}

if (phone) {
  staticData.notifiedUsers[phone] = now;
}

return [$input.item];
